fn main() {
    tauri_build::build();

    // On Windows, tauri-plugin-dialog (rfd) imports TaskDialogIndirect from comctl32.dll v6,
    // which requires the Common Controls v6 manifest generated by tauri-build.
    // tauri-build links resource.lib into bin targets, so we also link it into test binaries.
    #[cfg(target_os = "windows")]
    if let Ok(out_dir) = std::env::var("OUT_DIR") {
        let out = std::path::PathBuf::from(out_dir);
        for candidate in ["libresource.a", "resource.lib"] {
            let res = out.join(candidate);
            if res.exists() {
                println!("cargo:rustc-link-arg-tests={}", res.display());
                break;
            }
        }
    }
}
